public static int factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

public static int fibonacci(int n) {
    if (n <= 1) return n;
    int prev2 = 0, prev1 = 1;
    for (int i = 2; i <= n; i++) {
        int current = prev1 + prev2;
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

public static <T> void quickSort(T[] arr, int low, int high, Comparator<T> comp) {
    if (low < high) {
        int pivotIndex = partition(arr, low, high, comp);
        quickSort(arr, low, pivotIndex - 1, comp);
        quickSort(arr, pivotIndex + 1, high, comp);
    }
}

private static <T> int partition(T[] arr, int low, int high, Comparator<T> comp) {
    T pivot = arr[high];
    int i = low - 1;
    for (int j = low; j < high; j++) {
        if (comp.compare(arr[j], pivot) <= 0) {
            i++;
            T temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }
    T temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;
    return i + 1;
}

public static <T> List<T> flatten(List<List<T>> lists) {
    return lists.stream()
        .flatMap(Collection::stream)
        .collect(Collectors.toList());
}

public static <K, V> Map<K, V> zipToMap(List<K> keys, List<V> values) {
    if (keys.size() != values.size()) {
        throw new IllegalArgumentException("Keys and values must have same size");
    }
    return IntStream.range(0, keys.size())
        .boxed()
        .collect(Collectors.toMap(keys::get, values::get));
}

public static String formatName(String firstName, String lastName) {
    if (firstName == null && lastName == null) {
        return "";
    }
    if (firstName == null) return lastName.trim();
    if (lastName == null) return firstName.trim();
    return String.format("%s %s", firstName.trim(), lastName.trim());
}

public static <T> Predicate<T> not(Predicate<T> predicate) {
    return predicate.negate();
}

public static <T> Predicate<T> and(Predicate<T>... predicates) {
    return Arrays.stream(predicates)
        .reduce(Predicate::and)
        .orElse(t -> true);
}

public static <T> List<List<T>> partition(List<T> list, int size) {
    if (size <= 0) throw new IllegalArgumentException("Size must be positive");
    return IntStream.range(0, (list.size() + size - 1) / size)
        .mapToObj(i -> list.subList(i * size, Math.min((i + 1) * size, list.size())))
        .collect(Collectors.toList());
}

public static <T> Optional<T> findFirst(List<T> list, Predicate<T> predicate) {
    for (T item : list) {
        if (predicate.test(item)) {
            return Optional.of(item);
        }
    }
    return Optional.empty();
}

public static double average(int[] numbers) {
    if (numbers.length == 0) return 0;
    int sum = 0;
    for (int num : numbers) {
        sum += num;
    }
    return (double) sum / numbers.length;
}

public static <T extends Comparable<T>> T findMax(List<T> list) {
    if (list == null || list.isEmpty()) {
        throw new IllegalArgumentException("List cannot be null or empty");
    }
    T max = list.get(0);
    for (T item : list) {
        if (item.compareTo(max) > 0) {
            max = item;
        }
    }
    return max;
}

public static <T> Supplier<T> memoize(Supplier<T> supplier) {
    AtomicReference<T> cached = new AtomicReference<>();
    AtomicBoolean initialized = new AtomicBoolean(false);
    return () -> {
        if (!initialized.getAndSet(true)) {
            cached.set(supplier.get());
        }
        return cached.get();
    };
}

public static String repeat(String str, int count) {
    if (count < 0) throw new IllegalArgumentException("Count cannot be negative");
    StringBuilder sb = new StringBuilder(str.length() * count);
    for (int i = 0; i < count; i++) {
        sb.append(str);
    }
    return sb.toString();
}

public static <T, R> Function<T, R> compose(Function<T, R>... functions) {
    if (functions.length == 0) {
        throw new IllegalArgumentException("At least one function required");
    }
    return Arrays.stream(functions)
        .reduce(Function::andThen)
        .orElse(Function.identity());
}
